    // so two sources that differ only past the cut never compare equal.
    if (key.length > ANCHOR_SOURCE_MAX) key = key.slice(0, ANCHOR_SOURCE_MAX - 9) + '~' + anchorDigest(key);
    return ANCHOR_SOURCE_PREFIX + key;
