    if (!parent || !parent.closest) return null;
    var region = null;
    try { region = parent.closest(CONTEXT_LANDMARK_SELECTOR); } catch (ex) { return null; }
    if (!region || region === document.body) return null;
    var seg = ctxSegment(region);
