    if (vimLastActionId === 'wordBackward') return 'PREVIOUS WORD';
    if (vimLastActionId === 'wordEnd') return 'EXACT TOKEN';
    if (vimLastActionId === 'lineStart') return 'TO LINE START';
    if (vimLastActionId === 'lineEnd') return 'TO LINE END';
